import{_ as n,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"macOS-Berechtigungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/permissions.md","filePath":"de/guide/permissions.md","lastUpdated":1793163976000}'),a={name:"de/guide/permissions.md"};function s(g,e,u,o,h,d){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="macos-berechtigungen" tabindex="-1">macOS-Berechtigungen <a class="header-anchor" href="#macos-berechtigungen" aria-label="Permalink to &quot;macOS-Berechtigungen&quot;">​</a></h1><p>NueZip kann einige macOS-Berechtigungen anfordern, um das beste Erlebnis zu bieten. Diese Seite erklärt, wofür jede Berechtigung dient und wie Sie sie verwalten.</p><h2 id="dateien-und-ordner" tabindex="-1">Dateien und Ordner <a class="header-anchor" href="#dateien-und-ordner" aria-label="Permalink to &quot;Dateien und Ordner&quot;">​</a></h2><p>Um von überall auf Ihrem System auf Archive zuzugreifen, benötigt NueZip die Dateizugriffsberechtigung.</p><p><strong>Wofür sie genutzt wird</strong>: Lesen von Archivdateien, Extrahieren von Inhalten und Erstellen neuer Archive.</p><p><strong>Verwalten</strong>: Systemeinstellungen → <strong>Datenschutz &amp; Sicherheit</strong> → <strong>Dateien und Ordner</strong></p><p>Gewähren Sie den Zugriff, wenn Sie beim ersten Start dazu aufgefordert werden. Sie können den Zugriff jederzeit verwalten oder widerrufen.</p><h2 id="finder-erweiterung" tabindex="-1">Finder-Erweiterung <a class="header-anchor" href="#finder-erweiterung" aria-label="Permalink to &quot;Finder-Erweiterung&quot;">​</a></h2><p>NueZip enthält eine Finder-Erweiterung, die Optionen für das Kontextmenü per Rechtsklick hinzufügt.</p><p><strong>Wofür sie genutzt wird</strong>: Klicken Sie im Finder mit der rechten Maustaste auf Archivdateien, um sie direkt mit NueZip zu extrahieren, zu komprimieren oder zu öffnen.</p><p><strong>Aktivieren</strong>: Systemeinstellungen → <strong>Datenschutz &amp; Sicherheit</strong> → <strong>Erweiterungen</strong> → <strong>Finder-Erweiterungen</strong> → <strong>NueZip</strong> aktivieren</p><h2 id="benachrichtigungen" tabindex="-1">Benachrichtigungen <a class="header-anchor" href="#benachrichtigungen" aria-label="Permalink to &quot;Benachrichtigungen&quot;">​</a></h2><p>NueZip kann Benachrichtigungen für zeitaufwändige Vorgänge anzeigen (Stapelextraktion, große Archivkomprimierung).</p><p><strong>Wofür sie genutzt wird</strong>: Benachrichtigung, wenn ein Hintergrundvorgang abgeschlossen ist.</p><p><strong>Verwalten</strong>: Systemeinstellungen → <strong>Benachrichtigungen</strong> → <strong>NueZip</strong></p><h2 id="vollstandiger-datentragerzugriff-optional" tabindex="-1">Vollständiger Datenträgerzugriff (Optional) <a class="header-anchor" href="#vollstandiger-datentragerzugriff-optional" aria-label="Permalink to &quot;Vollständiger Datenträgerzugriff (Optional)&quot;">​</a></h2><p>Zum Extrahieren von Archiven an systemgeschützte Orten kann NueZip Vollständigen Datenträgerzugriff anfordern.</p><p><strong>Wofür er genutzt wird</strong>: Extrahierte Dateien an Orte außerhalb Ihres Benutzerordners schreiben.</p><p><strong>Verwalten</strong>: Systemeinstellungen → <strong>Datenschutz &amp; Sicherheit</strong> → <strong>Vollständiger Datenträgerzugriff</strong></p><p>Diese Berechtigung ist optional und nur erforderlich, wenn Sie mit systemweiten Orten arbeiten.</p><h2 id="eine-berechtigung-mit-dem-terminal-zurucksetzen" tabindex="-1">Eine Berechtigung mit dem Terminal zurücksetzen <a class="header-anchor" href="#eine-berechtigung-mit-dem-terminal-zurucksetzen" aria-label="Permalink to &quot;Eine Berechtigung mit dem Terminal zurücksetzen&quot;">​</a></h2><p>Wenn ein Berechtigungsdialog abgelehnt wurde oder der Zustand inkonsistent ist, können Sie die macOS-Berechtigungsabfragen mit <code>tccutil</code> zurücksetzen:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Berechtigungen für NueZip zurücksetzen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.nuezip</span></span></code></pre></div><p>Nach dem Ausführen von <code>tccutil</code> starten Sie die App neu und rufen die Funktion erneut auf, um erneut dazu aufgefordert zu werden.</p><h2 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h2><ul><li>Wenn keine Benachrichtigungen erscheinen, prüfen Sie, ob die <strong>Benachrichtigungen</strong>-Berechtigung gewährt ist.</li><li>Nach dem Ändern von Berechtigungen beenden Sie NueZip stets und öffnen es erneut, damit die Änderungen wirksam werden.</li></ul><p>Für weitere Hilfe besuchen Sie die <a href="./troubleshooting.html">Fehlerbehebungsanleitung</a>.</p>`,27)])])}const p=n(a,[["render",s]]);export{c as __pageData,p as default};
